window.kbPageData["views/entry/k-59e2dee75413cecc"] = {"key":"entry/k-59e2dee75413cecc","state":{"route":"entry/k-59e2dee75413cecc"},"node":{"id":"k-59e2dee75413cecc","mode":"k","title":"2026 世界人工智能大会主旨讲话《携手构建公正合理的全球人工智能治理体系》（7 月 17 日）","type":"事实与事件","domain":"科技","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["digital","innovation"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["科技"],"时间索引":["年度事件或数据"],"来源主题":["重要会议讲话"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"2026 世界人工智能大会主旨讲话《携手构建公正合理的全球人工智能治理体系》（7 月 17 日）","slug":"795479d5cc94"}],"directorySummary":"考点三十 2026 世界人工智能大会主旨讲话《携手构建公正合理的全球人工智能治\n理体系》（7 月 17 日）\n发表题为《携手构建公正合理的全球人工智能治理体系》的主旨讲话，大会主题为“智能伙伴\n共创未来”。讲话提出“四个时代之问”：当机器开始思考，人类如何与之相处？当算法参与\n决策，安全如何保障？当…","sources":[{"id":"27be298a0cd273f1","label":"2026 世界人工智能大会主旨讲话《携手构建公正合理的全球人工智能治理体系》（7 月 17 日）","topic":"重要会议讲话","category":"时政","text":"考点三十 2026 世界人工智能大会主旨讲话《携手构建公正合理的全球人工智能治\n理体系》（7 月 17 日）\n发表题为《携手构建公正合理的全球人工智能治理体系》的主旨讲话，大会主题为“智能伙伴\n共创未来”。讲话提出“四个时代之问”：当机器开始思考，人类如何与之相处？当算法参与\n决策，安全如何保障？当技术挑战伦理，治理如何跟上？当鸿沟不断拉大，普惠如何实现？\n中方主张各国秉持以人为本、向上向善理念，让人工智能成为促进共同繁荣、维护共同安全的\n重要动力源，并提出四点意见：\n第一，坚持开放共赢，驱动创新发展，鼓励开源开放、合作共享，推进传统产业改造升级、新\n兴产业培育壮大、未来产业前瞻布局；\n第二，强化风险意识，确保安全可控，确保人工智能始终处于人类控制之下，共同反对泛化国\n家安全概念、把本国安全凌驾于他国安全之上；\n第三，鼓励包容并蓄，促进文明互鉴；\n第四，倡导和衷共济，完善全球治理，发挥联合国重要作用，帮助全球南方国家弥合数智鸿\n沟。\n宣布中国智能经济核心产业规模已超万亿元人民币。\n世界人工智能合作组织（政府间国际组织，7 月 16 日成立，总部上海，29 个成员国）在上海\n应运而生；未来 5 年中国将向发展中国家提供 5000 个人工智能专题研修培训名额，建设国际\n人工智能应用合作中心，推动气象智能预警方案“妈祖”在 30 个国家落地。\n会议发表主席声明，提出“同球共济”精神，强调创新是核心驱动力，倡导培育以企业为主\n体、以市场为牵引、以应用为导向、以科研为基础、以人才为根本的创新生态，开源开放是普\n惠发展的重要路径。","source":{"doc":"4e539a366dce19555ccf","first":7,"last":7,"page":7,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"innovation","title":"科技创新与科研组织"},{"slug":"digital","title":"数字技术与公共生活"}],"units":{"k-59e2dee75413cecc":[]}};
